-- Library Health Center (#165).
--
-- A health report is a cached snapshot so the admin page opens instantly
-- instead of walking the library on every request. Findings are plain rows
-- with a severity, category, evidence JSON and the safe actions the UI may
-- offer; nothing in this feature deletes an archive file.
--
-- Reports are generated by a background job (`library_health::run_report`)
-- which updates `progress`, `total` and `findings_count` while it runs. Only
-- the newest reports are kept; older rows are pruned after a successful run.

CREATE TABLE IF NOT EXISTS library_health_reports (
    id             INTEGER PRIMARY KEY AUTOINCREMENT,
    status         TEXT NOT NULL DEFAULT 'running',
    trigger        TEXT NOT NULL DEFAULT 'manual',
    progress       INTEGER NOT NULL DEFAULT 0,
    total          INTEGER NOT NULL DEFAULT 0,
    findings_count INTEGER NOT NULL DEFAULT 0,
    errors_count   INTEGER NOT NULL DEFAULT 0,
    warnings_count INTEGER NOT NULL DEFAULT 0,
    info_count     INTEGER NOT NULL DEFAULT 0,
    error          TEXT,
    started_at     TEXT NOT NULL,
    finished_at    TEXT
);

CREATE INDEX IF NOT EXISTS idx_library_health_reports_status
    ON library_health_reports(status, id DESC);

CREATE TABLE IF NOT EXISTS library_health_findings (
    id            INTEGER PRIMARY KEY AUTOINCREMENT,
    report_id     INTEGER NOT NULL REFERENCES library_health_reports(id) ON DELETE CASCADE,
    category      TEXT NOT NULL,
    kind          TEXT NOT NULL,
    severity      TEXT NOT NULL,
    game_id       INTEGER,
    version_id    INTEGER,
    root_id       INTEGER,
    path          TEXT,
    title         TEXT NOT NULL,
    detail        TEXT NOT NULL,
    evidence_json TEXT NOT NULL DEFAULT '{}',
    actions_json  TEXT NOT NULL DEFAULT '[]',
    created_at    TEXT NOT NULL
);

CREATE INDEX IF NOT EXISTS idx_library_health_findings_report
    ON library_health_findings(report_id, severity, id);
CREATE INDEX IF NOT EXISTS idx_library_health_findings_category
    ON library_health_findings(report_id, category);
